  [1231000] = { nil, "Subisce $N1 danni da fuoco ogni $N2 s.", nil, 0x608ea152, "mu" },
  [1231010] = { "Vishas marchia i giocatori nemici. Quando un bersaglio marchiato lancia un incantesimo, Vishas scaglia un coltello nella sua direzione.", "Se lanci un incantesimo, Vishas ti scaglierà contro un coltello.", 0x7aee6290, 0x87862931, "uu" },
  [1231011] = { "Vishas scaglia uno dei suoi pugnali verso un nemico, infliggendo $N1 danni da ombra al primo nemico che colpisce. Se il coltello colpisce un giocatore afflitto da Tortuous Rebuke, provoca anche un sanguinamento.", nil, 0x81333075, nil, "um" },
  [1231012] = { nil, "Vishas ti tormenta. Subisci $N1 danni da ombra ogni $N2 s.", nil, 0x610f4cae, "mu" },
  [1231024] = { "Prova di persona un Portiporter per capire il perché di tanto clamore.\n\nUtilizzabile solo a New Avalon e dopo aver verificato una relativa sicurezza con altre cavie.", nil, 0x5565caac, nil, "um" },
  [1231087] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
