  [1231095] = { "Assale la mente del bersaglio, infliggendo $N1 danni da ombra e aumentando di $N2 i danni da ombra subiti per $D1.", "Danni da ombra subiti aumentati di $N1.", 0xbee251eb, 0xc866cf0e, "uu" },
  [1231098] = { nil, "$N1 danni ogni $N2 secondi.", nil, 0x6e147642, "mu" },
  [1231102] = { "Attacca i nemici vicini in un turbine d'acciaio che dura $D1, infliggendo danni dell'arma più $N2 ogni $D2. Conferisce all'incantatore un'immunità temporanea alla magia.", "Immune alla magia.\nInfligge danni normali più $N1 ogni $D1 ai nemici vicini.", 0xd1fe8fef, 0x059c0337, "uu" },
  [1231123] = { "Evoca Pepe perché ti accompagni nelle tue avventure!", "Pepe si è unito a te nelle tue avventure!", 0x5d1b97e4, 0x08c375ce, "uu" },
  [1231124] = { "Ti cura di $N1 e aumenta la Forza di $N2 per $D1.", "Forza aumentata di $N1.", 0x246dbbdf, 0x90d9af1c, "uu" },
  [1231128] = { "Incanta in modo permanente un'arma da mischia in modo che, attaccando in mischia, spesso ti curi di $N1 e aumenti la Forza di $N2 per $D1.", nil, 0xb721ecf3, nil, "um" },
  [1231138] = { "Rigenera $N1 mana e aumenta la potenza magica di $N2 per $D1.", "Potenza magica aumentata di $N1.", 0x4fb14ee8, 0x4e1d481d, "uu" },
