  [1231301] = { "Subisce il $N1% di danni da fuoco ogni $D1 per $D2. Si cumula fino a $N4 volte.\n\nCausato dalle abilità dei New Avalon Watchman quando usano la torcia.", "Subisci il $N1% della tua salute massima come danni da fuoco ogni $D1.", 0xee124d49, 0xd7cd79c7, "uu" },
