  [1231317] = { "Infligge il $N1% della salute massima del bersaglio come danni fisici e un ulteriore $N2% ogni $D1 per $D2.\n\nAlla scadenza, la ferita ha una probabilità, basata sulla salute attuale del bersaglio, di trasformarsi in Idrofobia Animale.", "Subisci il $N1% della salute massima come danni fisici ogni $D1.\n\nQuando questo effetto termina, hai una probabilità di contrarre Idrofobia Animale che dipende da quanto è bassa la tua salute.", 0x5742609d, 0xb1bea5d8, "uu" },
  [1231324] = { "Velocità di movimento ridotta del $N1%. Subisce il $N2% della salute massima come danni fisici ogni $D1 per $D2.\n\nSe non ti curi, morirai.", "Velocità di movimento ridotta del $N1%. Subisci il $N2% della salute massima come danni fisici ogni $D1 per $D2.\n\nSe non vieni curato, morirai.", 0x415b1895, 0x3e9fb941, "uu" },
